struct Dag {obs_source_t *root;std::vector<std::array<obs_source_t*,2>> levels;};
Dag makeDag(int depth){Dag d;d.root=source("overflow root");for(int l=0;l<depth;l++){d.levels.push_back({source("overflow A"),source("overflow B")});if(l==0){for(auto *c:d.levels[l]){if(!obs_source_add_active_child(d.root,c))std::abort();node(d.root)->visual.push_back(c);}}else for(auto *p:d.levels[l-1])for(auto *c:d.levels[l]){if(!obs_source_add_active_child(p,c))std::abort();node(p)->visual.push_back(c);}}return d;}
void dispose(Dag &d){for(int l=int(d.levels.size())-2;l>=0;l--)for(auto *p:d.levels[l]){for(auto *c:d.levels[l+1])obs_source_remove_active_child(p,c);node(p)->visual.clear();}for(auto *c:d.levels[0])obs_source_remove_active_child(d.root,c);node(d.root)->visual.clear();for(auto &v:d.levels)for(auto *s:v)obs_source_release(s);obs_source_release(d.root);studio_graph_drain();}
bool zero(Dag &d){bool z=studio_graph_show(d.root)==0&&studio_graph_active(d.root)==0;for(auto &l:d.levels)for(auto *s:l)z &=studio_graph_show(s)==0&&studio_graph_active(s)==0;return z;}
struct StackTask{obs_source_t *root;bool activate;};
void *stackRun(void *v){auto *t=static_cast<StackTask*>(v);if(t->activate)obs_source_inc_active(t->root);else obs_source_dec_active(t->root);return nullptr;}
int main(int argc,char **argv){if(argc!=2||std::filesystem::exists(argv[1]))return 2;checks=obs_data_array_create();check(obs_startup("en-US",nullptr,nullptr),"Overflow native core startup");obs_source_info i{};i.id="graph_probe";i.type=OBS_SOURCE_TYPE_INPUT;i.output_flags=0;i.get_name=name;i.create=create;i.destroy=destroy;i.enum_active_sources=enumerate;i.enum_all_sources=enumerate;obs_register_source(&i);
 auto d=makeDag(32);obs_source_inc_active(d.root);check(zero(d),"2^31 leaf credit MAIN activation rejected before any node publication");obs_source_inc_showing(d.root);check(zero(d),"2^31 leaf credit AUX activation rejected before any node publication");obs_source_dec_active(d.root);obs_source_dec_showing(d.root);check(zero(d),"Failed activation published no own MAIN or AUX credit");
 obs_source_remove_active_child(d.root,d.levels[0][0]);node(d.root)->visual.erase(node(d.root)->visual.begin());obs_source_inc_active(d.root);count(d.levels.back()[0],1073741824L,1073741824L,"After overflow scratch cleanup, valid half DAG has exact2^30 credits");count(d.root,1,1,"Valid half DAG publishes one own MAIN credit");auto *la=d.levels.back()[0],*lb=d.levels.back()[1];check(!obs_source_add_active_child(lb,la),"Active edge that would exceed signed32 refused");count(la,1073741824L,1073741824L,"Rejected active attachment changes no credits");obs_source_remove_active_child(lb,la);count(la,1073741824L,1073741824L,"Rejected attachment left no removable edge");obs_source_inc_active(d.root);count(d.root,1,1,"Root current-plus-delta overflow rejected without own credit mutation");count(la,1073741824L,1073741824L,"Current-plus-delta overflow does not partially update leaves");
 auto *p=source("batch old parent"),*idle=source("batch idle parent"),*x=source("batch extra child");obs_source_inc_active(p);check(obs_source_add_active_child(p,la)&&obs_source_add_active_child(p,x),"Overflow batch setup attaches real active edges");node(p)->visual={la,x};count(la,1073741825L,1073741825L,"Overflow batch setup has exact2^30+1");check(!studio_graph_transfer_pair(p,idle,x,p,lb,la),"Later signed32 overflow aborts whole transfer batch");count(x,1,1,"Overflow batch rolls back earlier valid transfer credit");count(la,1073741825L,1073741825L,"Overflow batch restores failed move old credit");obs_source_remove_active_child(p,x);count(x,0,0,"Overflow batch restores exact original first edge ownership");obs_source_remove_active_child(p,la);node(p)->visual.clear();obs_source_dec_active(p);obs_source_release(p);obs_source_release(idle);obs_source_release(x);obs_source_dec_active(d.root);check(zero(d),"All credits return to zero after overflow/recovery");dispose(d);
 // Flat intrusive scratch avoids recursion on a4096-source real native chain.
 std::vector<obs_source_t*> chain;chain.reserve(4096);for(int n=0;n<4096;n++){auto *s=source("small-stack chain node");if(!chain.empty()){if(!obs_source_add_active_child(chain.back(),s))std::abort();node(chain.back())->visual.push_back(s);}chain.push_back(s);}pthread_attr_t attr;pthread_attr_init(&attr);int stackRc=pthread_attr_setstacksize(&attr,65536);check(stackRc==0,"Native accounting worker has explicit64KiB stack");StackTask task{chain[0],true};pthread_t thread;auto start=std::chrono::steady_clock::now();int createRc=pthread_create(&thread,&attr,stackRun,&task);int joinRc=createRc?createRc:pthread_join(thread,nullptr);auto elapsed=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-start).count();check(createRc==0&&joinRc==0,"4096-node chain activation returns on64KiB worker stack");count(chain.back(),1,1,"4096-node chain preserves exact MAIN credit");task.activate=false;createRc=pthread_create(&thread,&attr,stackRun,&task);joinRc=createRc?createRc:pthread_join(thread,nullptr);check(createRc==0&&joinRc==0,"4096-node chain deactivation returns on64KiB worker stack");count(chain.back(),0,0,"4096-node chain returns to zero");pthread_attr_destroy(&attr);for(int n=4094;n>=0;n--){obs_source_remove_active_child(chain[n],chain[n+1]);node(chain[n])->visual.clear();}for(auto *s:chain)obs_source_release(s);studio_graph_drain();obs_shutdown();auto *r=obs_data_create();obs_data_set_array(r,"checks",checks);obs_data_set_int(r,"failures",failures);obs_data_set_bool(r,"passed",!failures);obs_data_set_int(r,"chain_activation_plus_thread_setup_ns",elapsed);obs_data_set_int(r,"chain_vertices",4096);obs_data_set_int(r,"worker_stack_bytes",65536);obs_data_set_string(r,"scope","Native real accounting signed32 boundary, all-or-nothing failed graph/root/batch updates and small-stack long chain. No Windows process, GPU, or media.");obs_data_save_json_safe(r,argv[1],"tmp",nullptr);obs_data_release(r);obs_data_array_release(checks);return failures?1:0;}
